// Des: Tests for te-zsim-page: the simulator loads, is bilingual, virtualizes lists, switches drift
// Flo: load sim in headless Chrome > read AX tree > flip Z.set > read again
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const zsim = @import("te-zsim-page.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const T = std.testing;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "sim loads, shows chats and only a window of the 306 chats" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); const nodes = try snap.axSnap(alo, mok.conn); try T.expect(snap.findNode(nodes, "listitem", "Mom unread 2") != null); try T.expect(snap.findNode(nodes, "textbox", "Tìm kiếm") != null); const items = try snap.findAll(alo, nodes, "listitem", ""); try T.expect(items.len >= 6 and items.len <= 12); try T.expectEqualStrings("306", try snap.evalStr(alo, mok.conn, "String(Z.chats.length)")); }
test "language and drift switch rename the labels" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); _ = try snap.evalStr(alo, mok.conn, "Z.set('lang','en')"); var nodes = try snap.axSnap(alo, mok.conn); try T.expect(snap.findNode(nodes, "textbox", "Search") != null); try T.expect(snap.findNode(nodes, "button", "Send") != null); _ = try snap.evalStr(alo, mok.conn, "Z.set('drift','C')"); nodes = try snap.axSnap(alo, mok.conn); try T.expect(snap.findNode(nodes, "textbox", "Search") == null); try T.expect(snap.findNode(nodes, "textbox", "Xyz1") != null); }
test "opening a chat shows its messages with data attributes, history window is 30" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); _ = try snap.evalStr(alo, mok.conn, "openChat(Z.chats[12])"); try T.expectEqualStrings("30", try snap.evalStr(alo, mok.conn, "String(document.querySelectorAll('#thread [role=article]').length)")); try T.expectEqualStrings("them", try snap.evalStr(alo, mok.conn, "document.querySelector('#thread [role=article]').dataset.dir")); }
